import { zodResolver } from "@hookform/resolvers/zod";
import type { KeyboardEvent } from "react";
import { useForm } from "react-hook-form";
import { z } from "zod";
import { useSendMessage } from "../../entities/chat/api/queries";
import { currentUserId } from "../../entities/chat/api/mockData";
import type { ChatId } from "../../entities/chat/model/types";
import styles from "./MessageForm.module.scss";

const messageSchema = z.object({
  text: z.string().trim().min(1, "Введите сообщение").max(2_000),
});

type MessageFormValues = z.infer<typeof messageSchema>;

interface MessageFormProps {
  chatId: ChatId;
}

export function MessageForm({ chatId }: MessageFormProps) {
  const sendMessage = useSendMessage();
  const {
    handleSubmit,
    register,
    reset,
  } = useForm<MessageFormValues>({
    resolver: zodResolver(messageSchema),
    defaultValues: { text: "" },
  });

  const onSubmit = handleSubmit(async ({ text }) => {
    await sendMessage.mutateAsync({
      chatId,
      authorId: currentUserId,
      text: text.trim(),
    });
    reset();
  });

  const handleKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      void onSubmit();
    }
  };

  return (
    <form className={styles.root} onSubmit={onSubmit}>
      <label className={styles.label} htmlFor="message-text">
        Сообщение
      </label>
      <div className={styles.composer}>
        <textarea
          id="message-text"
          className={styles.input}
          rows={1}
          placeholder="Напишите сообщение..."
          onKeyDown={handleKeyDown}
          {...register("text")}
        />
        <div className={styles.actions}>
          <button
            className={styles.actionButton}
            type="button"
            aria-label="Упомянуть"
          >
            <svg
              width="19"
              height="20"
              viewBox="0 0 19 20"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M10.1269 20C8.48731 20 7.03793 19.7771 5.77876 19.3312C4.5196 18.8907 3.46136 18.2404 2.60406 17.3806C1.74676 16.5207 1.09842 15.4671 0.659052 14.2197C0.219684 12.9724 0 11.5446 0 9.93631C0 8.3811 0.222363 6.99045 0.66709 5.76433C1.11717 4.53822 1.76819 3.49788 2.62014 2.64331C3.47744 1.78344 4.51692 1.12792 5.73858 0.676752C6.9656 0.225584 8.35336 0 9.90186 0C11.4075 0 12.7256 0.244161 13.8562 0.732484C14.9921 1.2155 15.9405 1.87102 16.7014 2.69904C17.4676 3.52176 18.0409 4.44798 18.4213 5.47771C18.8071 6.50743 19 7.569 19 8.66242C19 9.43206 18.9625 10.2123 18.8875 11.0032C18.8125 11.7941 18.6544 12.5212 18.4133 13.1847C18.1722 13.8429 17.7998 14.3737 17.2961 14.7771C16.7978 15.1805 16.1227 15.3822 15.2707 15.3822C14.8957 15.3822 14.4831 15.3238 14.033 15.207C13.5829 15.0902 13.1837 14.8965 12.8354 14.6258C12.4872 14.3551 12.2809 13.9915 12.2166 13.535H12.1201C11.9915 13.8429 11.7933 14.1348 11.5254 14.4108C11.2628 14.6868 10.9172 14.9071 10.4886 15.0717C10.0653 15.2362 9.54822 15.3079 8.93739 15.2866C8.24084 15.2601 7.62733 15.1062 7.09687 14.8248C6.56641 14.5382 6.12169 14.1507 5.76269 13.6624C5.40905 13.1688 5.14114 12.5982 4.95897 11.9506C4.78215 11.2978 4.69374 10.5945 4.69374 9.84076C4.69374 9.1242 4.8009 8.46868 5.01523 7.8742C5.22955 7.27972 5.52693 6.75955 5.90736 6.31369C6.29315 5.86783 6.74323 5.51221 7.25761 5.24682C7.77735 4.97611 8.33728 4.80892 8.93739 4.74522C9.47321 4.69214 9.9608 4.71603 10.4002 4.81688C10.8395 4.91242 11.2012 5.05839 11.4852 5.25478C11.7692 5.44586 11.9487 5.65817 12.0237 5.89172H12.1201V5H13.824V12.1975C13.824 12.6433 13.9499 13.0361 14.2018 13.3758C14.4536 13.7155 14.8206 13.8853 15.3029 13.8853C15.8494 13.8853 16.2673 13.6996 16.5567 13.328C16.8514 12.9565 17.0523 12.3832 17.1595 11.6083C17.272 10.8333 17.3283 9.84076 17.3283 8.63057C17.3283 7.91932 17.2291 7.21868 17.0309 6.52866C16.838 5.83333 16.5433 5.18312 16.1468 4.57803C15.7556 3.97293 15.26 3.43949 14.6599 2.97771C14.0598 2.51592 13.3552 2.15499 12.5461 1.8949C11.7424 1.62951 10.8288 1.49682 9.80541 1.49682C8.54625 1.49682 7.41836 1.69055 6.42174 2.07803C5.43049 2.46019 4.58658 3.02017 3.89002 3.75796C3.19882 4.49045 2.67104 5.38217 2.30668 6.43312C1.94769 7.47877 1.76819 8.66773 1.76819 10C1.76819 11.3535 1.94769 12.5557 2.30668 13.6067C2.67104 14.6576 3.20685 15.5441 3.91413 16.2659C4.62676 16.9878 5.50818 17.5345 6.55838 17.906C7.60857 18.2829 8.81952 18.4713 10.1912 18.4713C10.7806 18.4713 11.362 18.4156 11.9353 18.3041C12.5086 18.1927 13.0149 18.0706 13.4543 17.9379C13.8937 17.8052 14.2098 17.707 14.4027 17.6433L14.8528 19.1083C14.5206 19.2463 14.0866 19.3843 13.5508 19.5223C13.0203 19.6603 12.4523 19.7744 11.8469 19.8646C11.2468 19.9549 10.6734 20 10.1269 20ZM9.19458 13.6624C9.91258 13.6624 10.4939 13.5191 10.9387 13.2325C11.3834 12.9459 11.7076 12.5133 11.9112 11.9347C12.1148 11.3562 12.2166 10.6263 12.2166 9.74522C12.2166 8.8535 12.1041 8.15817 11.879 7.65924C11.654 7.1603 11.3218 6.80998 10.8824 6.60828C10.443 6.40658 9.90186 6.30573 9.25888 6.30573C8.64805 6.30573 8.12563 6.46497 7.69162 6.78344C7.26297 7.0966 6.93345 7.51592 6.70305 8.0414C6.478 8.56157 6.36548 9.12951 6.36548 9.74522C6.36548 10.4246 6.45657 11.0642 6.63875 11.664C6.82093 12.2585 7.1183 12.7415 7.53088 13.1131C7.94346 13.4793 8.49803 13.6624 9.19458 13.6624Z"
                fill="#8D8D8D"
              />
            </svg>
          </button>
          <button
            className={styles.actionButton}
            type="button"
            aria-label="Прикрепить файл"
          >
            <svg
              width="20"
              height="21"
              viewBox="0 0 20 21"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M18.7279 9.19975L9.71231 18.2154C7.66206 20.2656 4.33794 20.2656 2.28769 18.2154C0.237437 16.1651 0.237437 12.841 2.28769 10.7907L11.3033 1.77513C12.6701 0.408291 14.8862 0.408291 16.253 1.77513C17.6199 3.14196 17.6199 5.35804 16.253 6.72487L7.59099 15.3869C6.90757 16.0703 5.79953 16.0703 5.11612 15.3869C4.4327 14.7035 4.4327 13.5955 5.11612 12.9121L12.7175 5.31066"
                stroke="#8D8D8D"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
            </svg>
          </button>
          <button
            className={styles.actionButton}
            type="button"
            aria-label="Добавить эмодзи"
          >
            <svg
              width="22"
              height="22"
              viewBox="0 0 22 22"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M6.75 12.75C6.75 12.75 8.25 14.75 10.75 14.75C13.25 14.75 14.75 12.75 14.75 12.75M13.75 7.75H13.76M7.75 7.75H7.76M20.75 10.75C20.75 16.2728 16.2728 20.75 10.75 20.75C5.22715 20.75 0.75 16.2728 0.75 10.75C0.75 5.22715 5.22715 0.75 10.75 0.75C16.2728 0.75 20.75 5.22715 20.75 10.75ZM14.25 7.75C14.25 8.02614 14.0261 8.25 13.75 8.25C13.4739 8.25 13.25 8.02614 13.25 7.75C13.25 7.47386 13.4739 7.25 13.75 7.25C14.0261 7.25 14.25 7.47386 14.25 7.75ZM8.25 7.75C8.25 8.02614 8.02614 8.25 7.75 8.25C7.47386 8.25 7.25 8.02614 7.25 7.75C7.25 7.47386 7.47386 7.25 7.75 7.25C8.02614 7.25 8.25 7.47386 8.25 7.75Z"
                stroke="#8D8D8D"
                stroke-width="1.5"
                stroke-linecap="round"
                stroke-linejoin="round"
              />
            </svg>
          </button>
        </div>
      </div>
      {/* {errors.text && (
        <p className={styles.error} role="alert">
          {errors.text.message}
        </p>
      )} */}
      {sendMessage.isError && (
        <p className={styles.error} role="alert">
          Не удалось отправить сообщение.
        </p>
      )}
      <button
        className={styles.submit}
        type="submit"
        disabled={sendMessage.isPending}
        aria-label={
          sendMessage.isPending ? "Отправка сообщения" : "Отправить сообщение"
        }
      >
        <svg
          width="15"
          height="13"
          viewBox="0 0 15 13"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M6.18583 6.46275H2.51916M2.46273 6.65709L0.906114 11.3069C0.783825 11.6722 0.72268 11.8548 0.766561 11.9673C0.804667 12.065 0.886509 12.139 0.987497 12.1672C1.10379 12.1997 1.27943 12.1206 1.63072 11.9626L12.7717 6.94911C13.1146 6.79481 13.286 6.71766 13.339 6.61049C13.3851 6.51738 13.3851 6.40813 13.339 6.31502C13.286 6.20784 13.1146 6.13069 12.7717 5.97639L1.62684 0.961233C1.27661 0.803631 1.10149 0.72483 0.985317 0.757155C0.884424 0.785228 0.80259 0.859085 0.764352 0.956581C0.720323 1.06884 0.780814 1.2511 0.901796 1.6156L2.46316 6.31977C2.48394 6.38237 2.49433 6.41368 2.49843 6.44569C2.50207 6.4741 2.50203 6.50286 2.49832 6.53126C2.49414 6.56326 2.48367 6.59453 2.46273 6.65709Z"
            stroke="white"
            stroke-width="1.5"
            stroke-linecap="round"
            stroke-linejoin="round"
          />
        </svg>
      </button>
    </form>
  );
}
